// Aviso al equipo de que alguien ha reservado. Solo si el tenant dice a qué correo
// (AVISO_RESERVAS_EMAIL en tenant.env; vacío = apagado, que es lo normal en un cliente).
// El correo sale de la cuenta conectada a la credencial `Gmail` y va con Reply-To a quien
// reservó: contestar al aviso es escribirle a esa persona.
const i = $('Reserva hecha').first().json;
const cfg = $('Config (editar por tenant)').first().json;
const destinos = String(cfg.aviso_reservas_email || '').split(',').map((s) => s.trim()).filter(Boolean);
if (!destinos.length) return [{ json: { _enviar: false, motivo: 'desactivado (AVISO_RESERVAS_EMAIL vacío)' } }];

const txt = (v) => (v === undefined || v === null ? '' : String(v).trim());
// Una cabecera no puede llevar saltos de línea: con ellos se inyectan cabeceras nuevas.
const cab = (v) => txt(v).replace(/[\r\n]+/g, ' ');
const correoValido = (v) => /^[^\s@<>,;"]+@[^\s@<>,;"]+\.[^\s@<>,;"]{2,}$/.test(v);

const t = DateTime.fromISO(txt(i.inicio), { setZone: true }).setZone('Europe/Madrid').setLocale('es');
const cuando = t.isValid ? t.toFormat("cccc d 'de' LLLL 'a las' HH:mm") : txt(i.inicio);
const email = txt(i.email).toLowerCase();
const telefono = txt(i.telefono);

// El panel es `panel.<dominio>` y los webhooks `lucia.<dominio>` (los cuatro subdominios
// de un tenant son fijos). Si la dirección no tiene esa forma, el aviso va sin enlace.
const publico = txt(cfg.webhook_publico);
const panel = /^https:\/\/lucia\./.test(publico) ? publico.replace('https://lucia.', 'https://panel.') : '';
const enlace = panel && txt(i.cita_id) ? `${panel}/admin/content/appointments/${txt(i.cita_id)}` : '';

const lineas = [
  `${txt(i.nombre) || 'Alguien'} ha reservado desde la web.`,
  '',
  `Servicio: ${txt(i.servicio)}`,
  `Cuándo: ${cuando}${txt(i.duracion_minutos) ? ` (${txt(i.duracion_minutos)} min)` : ''}`,
  '',
  `Nombre: ${txt(i.nombre)}`,
  `Correo: ${email}`,
  telefono ? `Teléfono: +${telefono.replace(/^\+/, '')}` : null,
  txt(i.empresa) ? `Empresa: ${txt(i.empresa)}` : null,
  ...(txt(i.mensaje) ? ['', 'Qué quiere resolver:', txt(i.mensaje)] : []),
  ...(enlace ? ['', `La cita en el panel: ${enlace}`] : []),
  '',
  'La invitación con el enlace de Meet le llega por separado. Si Google no pudiera mandarla,',
  'aparecerá una tarea en el panel. Respondiendo a este correo le escribes a quien ha reservado.',
].filter((l) => l !== null);

const b64 = (s) => Buffer.from(s, 'utf8').toString('base64');
const palabra = (s) => `=?UTF-8?B?${b64(s)}?=`; // RFC 2047: tildes en el asunto
const asunto = `Nueva reserva: ${cab(i.nombre) || 'sin nombre'} · ${cab(cuando)}`;
const cabeceras = [
  `To: ${destinos.filter(correoValido).join(', ')}`,
  `Subject: ${palabra(asunto)}`,
  correoValido(email) ? `Reply-To: ${email}` : null,
  'MIME-Version: 1.0',
  'Content-Type: text/plain; charset=UTF-8',
  'Content-Transfer-Encoding: base64',
].filter(Boolean);
if (!destinos.some(correoValido)) {
  throw new Error('AVISO_RESERVAS_EMAIL no tiene ningún correo válido: ' + destinos.join(', '));
}
const cuerpo = b64(lineas.join('\r\n')).match(/.{1,76}/g).join('\r\n');
const mime = cabeceras.join('\r\n') + '\r\n\r\n' + cuerpo;
// La API de Gmail quiere el mensaje entero en base64url.
const raw = Buffer.from(mime, 'utf8').toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
return [{ json: { _enviar: true, raw, para: destinos, asunto } }];

// Un aviso que no sale tiene que verse: la ejecución acaba en error, no en verde.
const r = $json ?? {};
const st = r.statusCode ?? 0;
if (st >= 200 && st < 300) {
  const c = $('Code · Correo').first().json;
  return [{ json: { ok: true, id: (r.body && r.body.id) || null, para: c.para, asunto: c.asunto } }];
}
const b = r.body || {};
throw new Error(`Gmail rechazó el aviso (${st}): ${(b.error && b.error.message) || JSON.stringify(b).slice(0, 300)}`);
